const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry Definition: Get Cambodia's boundary
    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level0');
    const cambodia = gaul.filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));

    if (cambodia.size().getInfo() === 0) {
      console.log("Error: Could not find Cambodia in the administrative boundaries dataset.");
      console.log("C3"); // Calculation Failure due to geometry issue
      return;
    }
    const geom = cambodia.geometry();

    // 2. Data Acquisition: Load Hansen Global Forest Change v1.8 (up to 2020)
    // The 'loss' band represents forest loss between 2001 and 2014 (or up to 2020 for later versions).
    // The question specifically asks for 2001-2014. The 'loss' band in this dataset covers that period.
    // Documentation: https://developers.google.com/earth-engine/datasets/catalog/UMD_hansen_global_forest_change_v1_8
    const gfc = ee.Image('UMD/hansen/global_forest_change_v1_8');

    // Check if the image collection is empty (not applicable for a single image, but good practice for collections)
    // This dataset is a single image, so we expect it to exist.
    if (!gfc) {
        console.log("C1"); // Image not found (unlikely for a standard dataset)
        return;
    }

    // 3. Processing:
    // Define forest as areas with at least 10% tree cover in the year 2000.
    const forest2000 = gfc.select('treecover2000').gte(10); // Binary: 1 if forest, 0 otherwise

    // Select the 'loss' band, which indicates forest loss during 2001-2014 (1 for loss, 0 for no loss).
    const loss = gfc.select('loss');

    // Mask the loss to only include areas that were forest in 2000.
    const forestLoss2001_2014 = loss.updateMask(forest2000);

    // Calculate the area of each pixel. Use a scale appropriate for national level analysis.
    const pixelArea = ee.Image.pixelArea().addBands(forestLoss2001_2014); // Add the loss band to calculate its area.

    // Calculate total forest loss area (where forestLoss2001_2014 is 1)
    // Use a large scale (e.g., 1000m) for country-wide calculation to avoid memory issues.
    const stats = pixelArea.reduceRegion({
      reducer: ee.Reducer.sum().unweighted(), // sum of area where loss is 1
      geometry: geom,
      scale: 1000, // 1 km resolution for calculation
      maxPixels: 1e9 // Allow a large number of pixels
    });

    const totalLossAreaSqM = stats.get('loss').getInfo();
    const totalLossAreaSqKm = totalLossAreaSqM / 1e6;

    // Validate if the result is valid
    if (totalLossAreaSqM === null || isNaN(totalLossAreaSqM)) {
      console.log("C3"); // Calculation failed
      return;
    }

    // To check C2: calculate valid pixels for forestLoss2001_2014 within Cambodia.
    const validPixels = forestLoss2001_2014.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    }).get('loss').getInfo();

    console.log(`Forest Loss (2001-2014) in Cambodia (treecover >= 10%):`);
    console.log(`Total area of identified forest loss: ${totalLossAreaSqKm.toFixed(2)} sq km`);
    console.log(`Valid pixels counted: ${validPixels}`);

    // 5. Validation & Final Answer
    if (validPixels === 0) {
      console.log("C2"); // No valid pixels after masking/processing for loss
    } else if (totalLossAreaSqKm > 0) {
      console.log("A");
    } else { // totalLossAreaSqKm is 0 or less (which it shouldn't be if >0 is checked)
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    console.log("D"); // General error/syntax/method error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
